feedbackvariables.text:
getop(e):=block([r], r:errcatch(op(e)), if r=[] then false else r[1]);
getargs(e):=block([r], r:errcatch(args(e)), if r=[] then [] else r[1]);
ep1: getargs(ans1);
ep2: getargs(ans2);
ep3: getargs(ans3);
ep4: getargs(ans4);
type1: is(getop(ans1)=cc);
type2: is(getop(ans2)=oo);
type3: is(getop(ans3)=cc);
type4: is(getop(ans4)=oo);
setab: setify([a,b]);
setbc: setify([b,c]);
s1: if length(ep1)=2 then setify(ep1) else {};
s2: if length(ep2)=2 then setify(ep2) else {};
s3: if length(ep3)=2 then setify(ep3) else {};
s4: if length(ep4)=2 then setify(ep4) else {};
pairing_ok: (type1 and type2 and type3 and type4) and ((s1=setab and s2=setab and s3=setbc and s4=setbc) or (s1=setbc and s2=setbc and s3=setab and s4=setab));
samepair_flag: (type1 and type3) and is(s1=s3) and (s1=setab or s1=setbc);
score_types1: (if type1 then 0.15 else 0)+(if type2 then 0.15 else 0)+(if type3 then 0.15 else 0)+(if type4 then 0.15 else 0);
score_pairing_ok: score_types1+0.4;
score_other1: score_types1;

getop(e):=block([r], r:errcatch(op(e)), if r=[] then false else r[1]);
getargs(e):=block([r], r:errcatch(args(e)), if r=[] then [] else r[1]);
ep1: getargs(ans1);
setab: setify([a,b]);
s1: if length(ep1)=2 then setify(ep1) else {};
porder: if is(s1=setab) then [p,q] else [q,p];
ta5: apply(cc, porder);
ta6: apply(oo, porder);
type5: is(getop(ans5)=cc);
type6: is(getop(ans6)=oo);
ep5: getargs(ans5);
ep6: getargs(ans6);
correctset: setify(porder);
orderset5: if length(ep5)=2 then setify(ep5) else {};
orderset6: if length(ep6)=2 then setify(ep6) else {};
swapped5: is(orderset5=correctset) and not is(ep5=porder);
swapped6: is(orderset6=correctset) and not is(ep6=porder);
flag5ok: is(ep5=porder);
flag6ok: is(ep6=porder);
total_score5: (if type5 then 0.25 else 0)+(if type6 then 0.25 else 0)+(if flag5ok then 0.25 else 0)+(if flag6ok then 0.25 else 0);
